CREATE OR REPLACE FUNCTION public.listing_question_parent_matches(p_parent_id uuid, p_listing_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
